<?php $title="Dashboard";require "includes/header.php";$rev=$conn->query("SELECT COALESCE(SUM(amount),0)n FROM sales")->fetch_assoc()["n"];$cust=$conn->query("SELECT COUNT(*)n FROM customers")->fetch_assoc()["n"];$leads=$conn->query("SELECT COUNT(*)n FROM leads")->fetch_assoc()["n"];$stock=$conn->query("SELECT COALESCE(SUM(stock),0)n FROM bicycles")->fetch_assoc()["n"];$hot=$conn->query("SELECT COUNT(*)n FROM leads WHERE score>=80")->fetch_assoc()["n"];$low=$conn->query("SELECT COUNT(*)n FROM bicycles WHERE stock<=5")->fetch_assoc()["n"];$r=$conn->query("SELECT s.invoice_no,c.name customer,b.name bicycle,s.amount FROM sales s JOIN customers c ON c.id=s.customer_id JOIN bicycles b ON b.id=s.bicycle_id ORDER BY s.id DESC LIMIT 5");?><div class="hero"><div class="orb"></div><h1>Welcome to SmartCycle AI 🚲</h1><p>AI-powered bicycle sales, customer intelligence & smart business management.</p></div><div class="grid kpis"><?php foreach([["Revenue",money($rev),"↗ Live sales"],["Customers",$cust,"Customer 360"],["Active Leads",$leads,$hot." hot leads"],["Inventory Units",$stock,$low." low-stock models"],["AI Health","92%","System insight"]] as $x):?><div class="card kpi"><div class="label"><?=$x[0]?></div><div class="value"><?=$x[1]?></div><div class="trend"><?=$x[2]?></div></div><?php endforeach;?></div><div class="grid two" style="margin-top:18px"><div class="card"><div class="section-title"><h2>📈 Revenue Pulse</h2><span class="badge">AI Analytics</span></div><div class="chartbox"><canvas id="c"></canvas></div></div><div class="card ai-card"><h2>✨ AI Action Center</h2><div class="feature"><b>🎯 <?=$hot?> Hot Leads</b>Prioritize high-score customers.</div><div class="feature" style="margin-top:9px"><b>📦 <?=$low?> Low Stock</b>Review inventory.</div><div class="feature" style="margin-top:9px"><b>🤝 Retention Opportunity</b>Invite recent buyers for service.</div><a class="btn primary" style="margin-top:12px" href="ai_assistant.php">Open AI Assistant →</a></div></div><div class="section-title"><h2>Recent Sales</h2><a href="sales.php">View all →</a></div><div class="card"><table><tr><th>Invoice</th><th>Customer</th><th>Cycle</th><th>Amount</th></tr><?php while($x=$r->fetch_assoc()):?><tr><td>#<?=e($x["invoice_no"])?></td><td><?=e($x["customer"])?></td><td><?=e($x["bicycle"])?></td><td><?=money($x["amount"])?></td></tr><?php endwhile;?></table></div><script>new Chart(document.getElementById("c"),{type:"line",data:{labels:["Jan","Feb","Mar","Apr","May","Jun","Jul"],datasets:[{label:"Revenue",data:[42000,51000,47000,68000,72000,86000,98000],tension:.35,fill:true}]},options:{responsive:true,maintainAspectRatio:false}});</script><?php require "includes/footer.php";?>